function shuffle(p,a){return a.slice().map(v=>({v,r:rand(p)})).sort((a,b)=>a.r-b.r).map(x=>x.v);}
function ambient(p){const options={landing:['A cargo tug pulls away while dock crews guide the next arrival.','A mechanic checks a mooring clamp, then waves the Raven clear.','A flight-control announcement disappears beneath an engine roar.','Dockhands wheel a sealed crate past the landing lights.'],market:['A vendor lowers a canopy against the weather.','A loader drone inches through a gap between crowded stalls.','Two traders compare manifests over a pot of steaming tea.','A courier slips through the crowd, keeping a parcel close.'],cantina:['A glass slides across the copper counter. Nobody looks up.','A distant booth goes quiet as a freighter crew comes inside.','A worn speaker trades music for a brief traffic advisory.','Sable refills a kettle while a tired pilot watches the window.'],tunnels:['Condensation ticks against a grated walkway.','A maintenance drone pauses beneath a humming cable tray.','A valve releases a slow ribbon of steam.','Bootsteps echo somewhere beyond the service hatch.'],hideout:['A work lamp swings gently above the salvage bench.','A crane repositions a crate behind the loading door.','Orrin sorts chipped components into carefully labeled trays.','An old cooling fan struggles, catches, and steadies.']};let i=Math.floor(rand(p)*4);if(i===p.lastAmbient[p.scene])i=(i+1)%4;p.lastAmbient[p.scene]=i;p.ambient=options[p.scene][i];}
function generate(p){const used=p.offers.map(j=>j.kind),recent=p.recent.slice(-3);let pool=families.filter(x=>!used.includes(x)&&!recent.includes(x));if(!pool.length)pool=families.filter(x=>!used.includes(x)&&x!==p.recent.at(-1));if(!pool.length)pool=families.filter(x=>!used.includes(x));const weights=pool.flatMap(k=>Array((k==='repair'&&p.power<50)||(k==='dispute'&&p.security>50)||(k==='recovery'&&p.supplies<50)?3:1).fill(k));const kind=pick(p,weights),s=shuffle(p,sites),issuer=pick(p,Object.keys(residents)),item=pick(p,['power regulator','navigation relay','coolant manifold','sealed tool case']);const job={id:'port_'+(++p.sequence),kind,title:pick(p,titles[kind]),issuer,item,lead1:s[0],lead2:s[1],target:s[2],scans:s.slice(0,3),reward:900+Math.floor(rand(p)*7)*100,evidence:[],flags:{},ready:false,resolution:null,combat:false,heat:p.security,disposition:pick(p,['cooperative','cautious','hostile']),complication:pick(p,['A shift change has scattered the witnesses.','A disputed docking fee has made everyone defensive.','The last cargo manifest was filed under the wrong berth.','A patrol inspection has interrupted local business.']),context:p.lastOutcome||'The port is balancing a busy shift and unreliable infrastructure.'};if(kind==='repair'){job.lead1='market';job.lead2='tunnels';job.target=pick(p,['landing','cantina','hideout']);}if(kind==='escort')job.lead1=pick(p,['landing','market','cantina']);if(kind==='escort'&&job.target===job.lead1)job.target='hideout';return job;}
function fill(p){while(p.offers.length<3)p.offers.push(generate(p));}
function create(seed){const p={version:1,rng:seed>>>0||1,sequence:0,turn:0,scene:'landing',weather:'Rain',power:45,security:30,supplies:45,visits:{landing:1},lastAmbient:{},ambient:'',recent:[],offers:[],active:null,history:[],lastOutcome:'',residents:Object.fromEntries(Object.keys(residents).map(id=>[id,{trust:0,memory:[]}]))};fill(p);ambient(p);return p;}
function brief(j){const a=names[j.lead1],b=names[j.lead2],t=names[j.target];return {recovery:`${residents[j.issuer].name} needs a ${j.item} recovered from ${t}. Inspect the cargo trail at ${a} and ask about the claim at ${b}.`,dispute:`Two crews claim the same shipment. Hear their accounts at ${a} and ${b}, then settle the dispute at ${t}.`,escort:`A courier needs passage from ${a} to ${t}. Pick them up, then prepare a quiet route through the Maintenance Tunnels or confront the guards.`,repair:`An infrastructure fault threatens ${t}. Collect a replacement at the Freight Market, isolate the circuit in the Maintenance Tunnels, then restore power at ${t}.`,trace:`A repeating signal is moving through the port. Take readings at ${j.scans.map(x=>names[x]).join(', ')}. The readings will identify the source.`,forgery:`Forged port permits are circulating. Compare the registry at ${a} with a shipment seal at ${b}, then decide what to do with the evidence at ${t}.`}[j.kind];}
function choices(p){const j=p.active,s=p.scene;if(!j)return[];if(j.ready)return s==='landing'?[{id:'claim',label:`Close the job · ${j.reward} cr + 40 XP`,detail:'Collect payment once. The district remembers the outcome.'}]:[];const out=[];const add=(id,label,detail='',ok=true)=>out.push({id,label,detail,disabled:!ok});const has=k=>j.evidence.includes(k);
if(j.kind==='recovery'){if(s===j.lead1&&!has('trail'))add('trail','Inspect the cargo trail','Record the shipment seal.');if(s===j.lead2&&!has('claim'))add('claimant','Ask about the ownership claim','Learn why the cargo was taken.');if(s==='tunnels'&&!j.flags.access)add('access','Open a maintenance approach',j.evidence.length?'A cargo clue provides the access sequence.':'Find a cargo clue first.',j.evidence.length>0);if(s===j.target){add('negotiate','Negotiate the cargo’s release',j.disposition==='cooperative'?'Cooperative claimants: one clue is enough.':'Requires both clues or trusted local standing.',j.evidence.length>=(j.disposition==='cooperative'?1:2)||p.residents[j.issuer].trust>=2);add('stealth','Retrieve it through the service route',j.heat>=60?'Extra patrols: requires maintenance access and both clues.':'Requires maintenance access.',!!j.flags.access&&(j.heat<60||j.evidence.length>=2));add('fight','Confront the armed claimants','Starts real combat. Injuries persist.');}}
if(j.kind==='dispute'){if(s===j.lead1&&!has('first'))add('first','Hear the first crew’s account','Record their version without choosing a side.');if(s===j.lead2&&!has('second'))add('second','Hear the second crew’s account','Compare the competing claims.');if(s===j.target){add('mediate','Broker a shared settlement','Both accounts required. Reduces patrol tension.',j.evidence.length>=2);add('side','Favor the crew offering a cut','One account required. +200 cr, but trust falls and tension rises.',j.evidence.length>=1);}}
if(j.kind==='escort'){if(s===j.lead1&&!j.flags.passenger)add('pickup','Meet the courier','They travel with you until the job is resolved.');if(s==='tunnels'&&j.flags.passenger&&!j.flags.path)add('path','Scout a concealed passage','Prepare a safe route around the patrols.');if(s===j.target&&j.flags.passenger){if(p.residents[j.issuer].trust>=2)add('clearance','Use your client’s trusted clearance','Local standing opens a direct, peaceful route.');add('quiet','Deliver the courier quietly','Requires a scouted maintenance passage.',!!j.flags.path);add('fight','Push through the checkpoint','Starts real combat. The courier waits under cover.');}}
if(j.kind==='repair'){if(s==='market'&&!j.flags.part)add('part','Collect the replacement component','Supplied by the client; no purchase needed.');if(s==='tunnels'&&!j.flags.isolated)add('isolate','Isolate the damaged circuit','Makes the repair safe.');if(s===j.target){add('restore','Install the component and restore power','Requires the component and an isolated circuit.',!!j.flags.part&&!!j.flags.isolated);add('crew','Hire a qualified repair crew · 200 cr','Requires circuit isolation. The crew supplies the replacement component.',!!j.flags.isolated);}}
if(j.kind==='trace'){if(j.scans.includes(s)&&!has(s))add('scan','Take a directional signal reading','This location can be sampled once per investigation.');if(j.evidence.length>=3&&s===j.target)add('source','Inspect and report the transmitter','Confirm the source and file the findings.');if(s==='cantina')add('sell','Sell the partial coordinates','Requires two readings. Lower payout; patrol tension rises.',j.evidence.length>=2);}
if(j.kind==='forgery'){if(s===j.lead1&&!has('registry'))add('registry','Copy the original registry','Record a verifiable reference.');if(s===j.lead2&&!has('seal'))add('seal','Inspect the shipment seal','Compare the permit against the physical cargo.');if(s===j.target){add('expose','Expose the forged permits','Both pieces of evidence required. Helps legitimate traders.',j.evidence.length>=2);add('bury','Sell your silence to the broker','One piece of evidence required. +200 cr; residents lose trust.',j.evidence.length>=1);}}
add('withdraw','Withdraw from this job','No payment. Client trust falls by one; the unfinished job closes.');return out;}
function resolve(p,method){const j=p.active;if(!j||j.ready)return;const selfish=['side','sell','bury'].includes(method),violent=method==='combat';j.ready=true;j.resolution=method;j.combat=false;if(['side','bury'].includes(method))j.reward+=200;if(method==='sell')j.reward=Math.max(300,j.reward-300);p.security=clamp(p.security+(selfish?14:violent?18:-8),0,100);if(j.kind==='repair')p.power=clamp(p.power+25,0,100);if(['recovery','dispute','forgery'].includes(j.kind))p.supplies=clamp(p.supplies+(selfish?-8:12),0,100);const r=p.residents[j.issuer];r.trust=clamp(r.trust+(selfish?-2:violent?0:1),-5,5);const line=`${j.title}: ${method}. ${selfish?'You profited at the port’s expense.':violent?'The job was settled with gunfire.':'You helped without escalating the situation.'}`;r.memory.push(line);r.memory=r.memory.slice(-4);p.lastOutcome=line;}
function act(p,id,payload={}){const done=(message,extra={})=>{p.turn++;return {changed:true,message,...extra}},reject=message=>({changed:false,message});const j=p.active;
if(j?.combat)return reject('Resolve the current encounter first.');
if(id==='move'){if(!links[p.scene]?.includes(payload.site))return reject('Use a connected route.');p.scene=payload.site;p.visits[p.scene]=(p.visits[p.scene]||0)+1;ambient(p);return done(p.ambient);}
if(id==='talk'){const npc=residents[payload.resident],r=p.residents[payload.resident];if(!npc||npc.site!==p.scene||!r)return reject('That resident is not here.');if(payload.apexPublic&&!r.apexKnown){r.apexKnown=true;r.spokenRecent=r.spokenRecent||[];const intro='The 3.2 Apex Protocol? So you are its leader. I will remember who is backing these jobs.';r.spokenRecent.push(intro);r.spokenRecent=r.spokenRecent.slice(-3);return done(intro);}const pool=[p.power>=65?'The lights are holding now. People can finally get a full shift done.':'The grid is struggling. Keep an eye on the service lamps.',p.security>=60?'Patrols are on edge. A quiet approach needs more preparation.':'The patrols are leaving most people alone. Let us keep it that way.',p.supplies>=60?'The stalls are stocked again. Legitimate traders are finding their feet.':'Parts are tight. Every missing crate means someone waits longer.',p.active?`You are working on ${p.active.title}. Follow the evidence before choosing your approach.`:'Three local leads are circulating. Read them before committing.',r.trust>0?'You have helped people here. I can put a little trust in that.':r.trust<0?'I remember who came out ahead in your last deal. Be straight with me.':'We have not worked together yet. I judge people by what they do.',r.memory.length?`What stays with me is this: ${r.memory.at(-1)}`:'There is no shared history between us yet. That can change.',p.weather==='Heavy rain'?'The rain is hammering the freight awnings. The tunnels still connect the back routes.':`It is ${p.weather.toLowerCase()} outside. The port keeps moving regardless.`,'You can walk away from a local job, but the client will remember. Nobody here forgets a broken agreement quickly.'];if(r.apexKnown)pool.push('I remember you lead Apex. Your decisions here reflect on more than one hunter.',r.trust<0?'A syndicate name will not erase what happened between us.':'Blackglass may be your headquarters, but trust here is still earned face to face.');r.spokenRecent=r.spokenRecent||[];const candidates=pool.filter(line=>!r.spokenRecent.includes(line));const line=pick(p,candidates.length?candidates:pool);r.spokenRecent.push(line);r.spokenRecent=r.spokenRecent.slice(-3);return done(line);}
if(id==='observe'){ambient(p);return done(p.ambient);}
if(id==='accept'){if(j)return reject('Finish the active local job first.');const offer=p.offers.find(x=>x.id===payload.id);if(!offer)return reject('That lead is no longer available.');p.active=offer;p.offers=p.offers.filter(x=>x.id!==offer.id);return done(`${offer.title} accepted. ${brief(offer)}`);}
if(!j)return reject('No active local job.');const option=choices(p).find(x=>x.id===id);if(!option||option.disabled)return reject('That approach is not available here yet.');
if(id==='claim'){if(!j.ready||p.scene!=='landing')return reject('Return to the Landing Bay.');const reward=j.reward,record={id:j.id,title:j.title,kind:j.kind,resolution:j.resolution,reward,issuer:j.issuer,apexSigned:!!j.apexSigned};p.history.push(record);p.history=p.history.slice(-30);p.recent.push(j.kind);p.recent=p.recent.slice(-6);p.active=null;p.weather=pick(p,['Rain','Mist','Clear intervals','Heavy rain']);fill(p);ambient(p);return done(`${record.title} closed. +${reward} credits and +40 XP.`,{reward,xp:40,record});}
if(id==='withdraw'){const r=p.residents[j.issuer];r.trust=clamp(r.trust-1,-5,5);const message=`${j.title}: Deadlock withdrew before finishing the job.`;r.memory.push(message);r.memory=r.memory.slice(-4);p.lastOutcome=message;p.history.push({id:j.id,title:j.title,kind:j.kind,resolution:'withdrawn',reward:0,issuer:j.issuer,apexSigned:!!j.apexSigned});p.history=p.history.slice(-30);p.recent.push(j.kind);p.recent=p.recent.slice(-6);p.active=null;fill(p);return done('Job withdrawn. No payment; client trust decreased. Other leads remain available.');}
if(id==='fight'){if(j.combat)return reject('The encounter is already active.');j.combat=true;return done('The confrontation becomes a live firefight.',{combat:true,jobId:j.id});}
if(id==='crew'){if(Number(payload.credits||0)<200)return reject('You need 200 credits to hire the crew.');resolve(p,'crew');return done('The repair crew restores the circuit. Return to the Landing Bay for payment.',{spend:200});}
const evidence={trail:'trail',claimant:'claim',first:'first',second:'second',registry:'registry',seal:'seal'};
if(evidence[id]){j.evidence.push(evidence[id]);return done(`Evidence recorded. ${j.evidence.length} lead${j.evidence.length===1?'':'s'} collected.`);}
if(id==='scan'){j.evidence.push(p.scene);return done(j.evidence.length>=3?`The readings converge on ${names[j.target]}. Inspect the transmitter there.`:`Reading recorded at ${names[p.scene]}. ${3-j.evidence.length} more needed.`);}
const flags={access:'access',pickup:'passenger',path:'path',part:'part',isolate:'isolated'};if(flags[id]){j.flags[flags[id]]=true;return done({access:'Service approach unlocked.',pickup:'The courier is with you.',path:'A safe passage is mapped.',part:'The replacement component is secured.',isolate:'Circuit isolated. The repair can proceed safely.'}[id]);}
resolve(p,id);return done('Objective resolved. Return to the Landing Bay to close the job and collect payment.');}
function combatOutcome(p,jobId,outcome){const j=p.active;if(!j||j.id!==jobId||!j.combat)return false;j.combat=false;if(outcome==='victory')resolve(p,'combat');else{p.scene='market';p.security=clamp(p.security+8,0,100);p.ambient='You withdraw into the market. The job remains open; quieter approaches are still possible.';}return true;}
const api={create,act,choices,brief,combatOutcome,names,links,residents,labels,families};root.PortEngine=api;if(typeof module!=='undefined')module.exports=api;
